def list_websites(filter_llms_txt=None, filter_llms_full_txt=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0352000" if __import__("os").path.isdir("./environment_mix/0352000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _client_meta():
        ip = _extra.get("request_ip") or _extra.get("ip") or _extra.get("x_forwarded_for")
        ua = _extra.get("user_agent") or _extra.get("ua")
        if ip is not None and not isinstance(ip, str):
            ip = None
        if ua is not None and not isinstance(ua, str):
            ua = None
        return ip, ua

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _enforce_rate_limit(logs, request_ip, tool):
        window_s = os.environ.get("LLMS_EXPLORER_RATE_WINDOW_SECONDS")
        limit_s = os.environ.get("LLMS_EXPLORER_RATE_LIMIT_PER_WINDOW")
        if not window_s or not limit_s:
            return None
        try:
            window = int(window_s)
            limit = int(limit_s)
        except Exception:
            return None
        if window <= 0 or limit <= 0:
            return None
        if not request_ip:
            return None
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=window)
        count = 0
        for r in logs:
            if r.get("request_ip") != request_ip:
                continue
            created = _parse_iso(r.get("created_at"))
            if created and created >= cutoff:
                count += 1
        if count >= limit:
            return _err("RATE_LIMIT", "rate limit exceeded", retry_after_seconds=window)
        return None

    start = time.time()
    req_ip, req_ua = _client_meta()

    # Validate inputs
    if filter_llms_txt is not None and not isinstance(filter_llms_txt, bool):
        logs = _load("api_request_logs.json")
        now_iso = _now_iso()
        msg = "filter_llms_txt must be a boolean"
        logs.append({
            "id": _gen_id("req"),
            "tool_name": "list_websites",
            "input": {"filter_llms_txt": filter_llms_txt, "filter_llms_full_txt": filter_llms_full_txt},
            "website_id": None,
            "request_ip": req_ip,
            "user_agent": req_ua,
            "status": "error",
            "error_message": msg,
            "duration_ms": max(0, int((time.time() - start) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)
        return _err("VALIDATION_ERROR", msg, field="filter_llms_txt")

    if filter_llms_full_txt is not None and not isinstance(filter_llms_full_txt, bool):
        logs = _load("api_request_logs.json")
        now_iso = _now_iso()
        msg = "filter_llms_full_txt must be a boolean"
        logs.append({
            "id": _gen_id("req"),
            "tool_name": "list_websites",
            "input": {"filter_llms_txt": filter_llms_txt, "filter_llms_full_txt": filter_llms_full_txt},
            "website_id": None,
            "request_ip": req_ip,
            "user_agent": req_ua,
            "status": "error",
            "error_message": msg,
            "duration_ms": max(0, int((time.time() - start) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)
        return _err("VALIDATION_ERROR", msg, field="filter_llms_full_txt")

    # Rate limit (if enabled)
    logs = _load("api_request_logs.json")
    rl_err = _enforce_rate_limit(logs, req_ip, "list_websites")
    if rl_err:
        now_iso = _now_iso()
        logs.append({
            "id": _gen_id("req"),
            "tool_name": "list_websites",
            "input": {"filter_llms_txt": filter_llms_txt, "filter_llms_full_txt": filter_llms_full_txt},
            "website_id": None,
            "request_ip": req_ip,
            "user_agent": req_ua,
            "status": "error",
            "error_message": rl_err["error"]["message"],
            "duration_ms": max(0, int((time.time() - start) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)
        return rl_err

    websites = _load("websites.json")

    # Filter active only, per rules
    rows = [w for w in websites if w.get("status") == "active"]

    if filter_llms_txt is True:
        rows = [w for w in rows if w.get("has_llms_txt") is True]
    if filter_llms_full_txt is True:
        rows = [w for w in rows if w.get("has_llms_full_txt") is True]

    # Sort by canonical_origin for stable listing, then id
    rows.sort(key=lambda w: ((w.get("canonical_origin") or ""), (w.get("id") or "")))

    # Log ok
    now_iso = _now_iso()
    logs.append({
        "id": _gen_id("req"),
        "tool_name": "list_websites",
        "input": {"filter_llms_txt": filter_llms_txt, "filter_llms_full_txt": filter_llms_full_txt},
        "website_id": None,
        "request_ip": req_ip,
        "user_agent": req_ua,
        "status": "ok",
        "error_message": None,
        "duration_ms": max(0, int((time.time() - start) * 1000)),
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("api_request_logs.json", logs)

    return {
        "data": rows,
        "meta": {
            "total": len(rows),
            "has_more": False,
            "next_cursor": None,
        },
    }

