def update_website(id, input_url=None, status=None, last_checked_at=None, **_extra):
    import json, os, datetime, time, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0352000" if __import__("os").path.isdir("./environment_mix/0352000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_or_err(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string", field=field)
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string", field=field)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _client_meta():
        ip = _extra.get("request_ip") or _extra.get("ip") or _extra.get("x_forwarded_for")
        ua = _extra.get("user_agent") or _extra.get("ua")
        if ip is not None and not isinstance(ip, str):
            ip = None
        if ua is not None and not isinstance(ua, str):
            ua = None
        return ip, ua

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _enforce_rate_limit(logs, request_ip, tool):
        window_s = os.environ.get("LLMS_EXPLORER_RATE_WINDOW_SECONDS")
        limit_s = os.environ.get("LLMS_EXPLORER_RATE_LIMIT_PER_WINDOW")
        if not window_s or not limit_s:
            return None
        try:
            window = int(window_s)
            limit = int(limit_s)
        except Exception:
            return None
        if window <= 0 or limit <= 0:
            return None
        if not request_ip:
            return None
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=window)
        count = 0
        for r in logs:
            if r.get("request_ip") != request_ip:
                continue
            created = _parse_iso(r.get("created_at"))
            if created and created >= cutoff:
                count += 1
        if count >= limit:
            return _err("RATE_LIMIT", "rate limit exceeded", retry_after_seconds=window)
        return None

    def _validate_input_url(u):
        if u is None:
            return None
        if not isinstance(u, str) or not u.strip():
            return _err("VALIDATION_ERROR", "input_url must be a non-empty string", field="input_url")
        # Only validate that it's a parseable http(s) URL
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return _err("VALIDATION_ERROR", "input_url is not a valid URL", field="input_url")
        scheme = (p.scheme or "").lower()
        if scheme not in ("http", "https"):
            return _err("VALIDATION_ERROR", "input_url must have http or https scheme", field="input_url")
        if not p.netloc:
            return _err("VALIDATION_ERROR", "input_url must include a hostname", field="input_url")
        return None

    start = time.time()
    req_ip, req_ua = _client_meta()

    if not isinstance(id, str) or not id:
        logs = _load("api_request_logs.json")
        now_iso = _now_iso()
        msg = "id must be a non-empty string"
        logs.append({
            "id": _gen_id("req"),
            "tool_name": "list_websites",
            "input": {"id": id, "input_url": input_url, "status": status, "last_checked_at": last_checked_at},
            "website_id": None,
            "request_ip": req_ip,
            "user_agent": req_ua,
            "status": "error",
            "error_message": msg,
            "duration_ms": max(0, int((time.time() - start) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)
        return _err("VALIDATION_ERROR", msg, field="id")

    # Validate status if provided
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string", field="status")
        if status not in ("active", "disabled"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled", field="status")

    # Validate input_url if provided
    uerr = _validate_input_url(input_url)
    if uerr:
        logs = _load("api_request_logs.json")
        now_iso = _now_iso()
        logs.append({
            "id": _gen_id("req"),
            "tool_name": "list_websites",
            "input": {"id": id, "input_url": input_url, "status": status, "last_checked_at": last_checked_at},
            "website_id": None,
            "request_ip": req_ip,
            "user_agent": req_ua,
            "status": "error",
            "error_message": uerr["error"]["message"],
            "duration_ms": max(0, int((time.time() - start) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)
        return uerr

    # Validate last_checked_at if provided (may ignore later)
    dt_last_checked, derr = _parse_iso_or_err(last_checked_at, "last_checked_at")
    if derr:
        logs = _load("api_request_logs.json")
        now_iso = _now_iso()
        logs.append({
            "id": _gen_id("req"),
            "tool_name": "list_websites",
            "input": {"id": id, "input_url": input_url, "status": status, "last_checked_at": last_checked_at},
            "website_id": None,
            "request_ip": req_ip,
            "user_agent": req_ua,
            "status": "error",
            "error_message": derr["error"]["message"],
            "duration_ms": max(0, int((time.time() - start) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)
        return derr

    logs = _load("api_request_logs.json")
    rl_err = _enforce_rate_limit(logs, req_ip, "update_website")
    if rl_err:
        now_iso = _now_iso()
        logs.append({
            "id": _gen_id("req"),
            "tool_name": "list_websites",
            "input": {"id": id, "input_url": input_url, "status": status, "last_checked_at": last_checked_at},
            "website_id": None,
            "request_ip": req_ip,
            "user_agent": req_ua,
            "status": "error",
            "error_message": rl_err["error"]["message"],
            "duration_ms": max(0, int((time.time() - start) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)
        return rl_err

    websites = _load("websites.json")
    website = None
    for w in websites:
        if w.get("id") == id:
            website = w
            break
    if website is None:
        now_iso = _now_iso()
        logs.append({
            "id": _gen_id("req"),
            "tool_name": "list_websites",
            "input": {"id": id, "input_url": input_url, "status": status, "last_checked_at": last_checked_at},
            "website_id": None,
            "request_ip": req_ip,
            "user_agent": req_ua,
            "status": "error",
            "error_message": "website not found",
            "duration_ms": max(0, int((time.time() - start) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)
        return _err("NOT_FOUND", "website not found", id=id)

    mutated = False
    now_iso = _now_iso()

    # Update mutable fields
    if input_url is not None:
        website["input_url"] = input_url.strip()
        mutated = True

    # Enforce lifecycle transitions
    if status is not None and status != website.get("status"):
        cur = website.get("status")
        allowed = {"active": ["disabled"], "disabled": ["active"]}
        if cur not in allowed or status not in allowed[cur]:
            msg = f"invalid status transition from {cur} to {status}"
            logs.append({
                "id": _gen_id("req"),
                "tool_name": "list_websites",
                "input": {"id": id, "input_url": input_url, "status": status, "last_checked_at": last_checked_at},
                "website_id": website.get("id"),
                "request_ip": req_ip,
                "user_agent": req_ua,
                "status": "error",
                "error_message": msg,
                "duration_ms": max(0, int((time.time() - start) * 1000)),
                "created_at": now_iso,
                "updated_at": now_iso,
            })
            _save("api_request_logs.json", logs)
            return _err("INVALID_TRANSITION", msg, from_status=cur, to_status=status)
        website["status"] = status
        mutated = True

    # last_checked_at: accept but keep consistent type; server may ignore if not permitted.
    if dt_last_checked is not None:
        # Ensure it's not earlier than created_at if created_at parseable
        created_dt = _parse_iso(website.get("created_at"))
        if created_dt and dt_last_checked.replace(tzinfo=None) < created_dt.replace(tzinfo=None):
            msg = "last_checked_at cannot be earlier than created_at"
            logs.append({
                "id": _gen_id("req"),
                "tool_name": "list_websites",
                "input": {"id": id, "input_url": input_url, "status": status, "last_checked_at": last_checked_at},
                "website_id": website.get("id"),
                "request_ip": req_ip,
                "user_agent": req_ua,
                "status": "error",
                "error_message": msg,
                "duration_ms": max(0, int((time.time() - start) * 1000)),
                "created_at": now_iso,
                "updated_at": now_iso,
            })
            _save("api_request_logs.json", logs)
            return _err("VALIDATION_ERROR", msg, field="last_checked_at")
        website["last_checked_at"] = last_checked_at
        mutated = True

    if not mutated:
        # No success without effect
        msg = "no fields to update"
        logs.append({
            "id": _gen_id("req"),
            "tool_name": "list_websites",
            "input": {"id": id, "input_url": input_url, "status": status, "last_checked_at": last_checked_at},
            "website_id": website.get("id"),
            "request_ip": req_ip,
            "user_agent": req_ua,
            "status": "error",
            "error_message": msg,
            "duration_ms": max(0, int((time.time() - start) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)
        return _err("VALIDATION_ERROR", msg)

    website["updated_at"] = _now_iso()
    _save("websites.json", websites)

    logs.append({
        "id": _gen_id("req"),
        "tool_name": "list_websites",
        "input": {"id": id, "input_url": input_url, "status": status, "last_checked_at": last_checked_at},
        "website_id": website.get("id"),
        "request_ip": req_ip,
        "user_agent": req_ua,
        "status": "ok",
        "error_message": None,
        "duration_ms": max(0, int((time.time() - start) * 1000)),
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("api_request_logs.json", logs)

    return {"website": website}

def list_website_checks(website_id=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0352000" if __import__("os").path.isdir("./environment_mix/0352000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs = _load("api_request_logs.json")
    req_ip = _extra.get("request_ip") or _extra.get("ip") or _extra.get("x_forwarded_for") or None
    ua = _extra.get("user_agent") or _extra.get("ua") or None

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    log_row = {
        "id": _new_id("req"),
        "tool_name": "list_websites",  # schema enum doesn't include this tool; map to closest existing tool
        "input": {"website_id": website_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort},
        "website_id": website_id if isinstance(website_id, str) else None,
        "request_ip": req_ip,
        "user_agent": ua,
        "status": "ok",
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    def _finalize_and_return(payload, ok=True, error_message=None):
        log_row["status"] = "ok" if ok else "error"
        log_row["error_message"] = error_message
        log_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        log_row["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
        logs.append(log_row)
        _save("api_request_logs.json", logs)
        return payload

    # Rate limiting (rolling window) if enabled via env
    try:
        window_s = int(os.environ.get("RATE_LIMIT_WINDOW_SECONDS", "0") or "0")
        max_req = int(os.environ.get("RATE_LIMIT_MAX_REQUESTS", "0") or "0")
    except Exception:
        window_s, max_req = 0, 0

    if window_s > 0 and max_req > 0 and req_ip:
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        def _parse_dt(s):
            if not isinstance(s, str): return None
            try:
                if s.endswith("Z"): s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        count = 0
        for r in logs:
            if r.get("request_ip") != req_ip:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                count += 1
        if count >= max_req:
            return _finalize_and_return(_err("RATE_LIMIT", "Too many requests"), ok=False, error_message="rate_limited")

    # Validate inputs
    if website_id is not None and not isinstance(website_id, str):
        return _finalize_and_return(_err("VALIDATION_ERROR", "website_id must be a string"), ok=False, error_message="validation_error")
    if status is not None:
        if not isinstance(status, str):
            return _finalize_and_return(_err("VALIDATION_ERROR", "status must be a string"), ok=False, error_message="validation_error")
        if status not in ("queued", "running", "succeeded", "failed"):
            return _finalize_and_return(_err("VALIDATION_ERROR", "Invalid status"), ok=False, error_message="validation_error")
    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            return _finalize_and_return(_err("VALIDATION_ERROR", "limit must be an integer"), ok=False, error_message="validation_error")
        if limit < 1 or limit > 200:
            return _finalize_and_return(_err("VALIDATION_ERROR", "limit out of range"), ok=False, error_message="validation_error")
        limit_v = limit
    if cursor is not None and not isinstance(cursor, str):
        return _finalize_and_return(_err("VALIDATION_ERROR", "cursor must be a string"), ok=False, error_message="validation_error")
    if sort is None:
        sort_v = "created_at_desc"
    else:
        if not isinstance(sort, str):
            return _finalize_and_return(_err("VALIDATION_ERROR", "sort must be a string"), ok=False, error_message="validation_error")
        if sort not in ("created_at_desc", "created_at_asc"):
            return _finalize_and_return(_err("VALIDATION_ERROR", "Invalid sort"), ok=False, error_message="validation_error")
        sort_v = sort

    websites = _load("websites.json")
    website_by_id = {w.get("id"): w for w in websites if isinstance(w, dict) and isinstance(w.get("id"), str)}
    if website_id is not None and website_id not in website_by_id:
        # Filter references a missing website id => validation error (invalid filter reference)
        return _finalize_and_return(_err("NOT_FOUND", "Website not found", website_id=website_id), ok=False, error_message="website_not_found")

    checks = _load("website_checks.json")
    # Enforce FK integrity at read-time: ignore dangling checks (shouldn't exist)
    filtered = []
    for c in checks:
        if not isinstance(c, dict):
            continue
        wid = c.get("website_id")
        if not isinstance(wid, str) or wid not in website_by_id:
            continue
        if website_id is not None and wid != website_id:
            continue
        if status is not None and c.get("status") != status:
            continue
        filtered.append(c)

    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    reverse = (sort_v == "created_at_desc")
    filtered.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min, r.get("id") or ""), reverse=reverse)

    # Cursor handling (opaque)
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("idx:"):
                start = int(raw.split(":", 1)[1])
            else:
                start = int(raw)
            if start < 0:
                start = 0
        except Exception:
            return _finalize_and_return(_err("VALIDATION_ERROR", "Invalid cursor"), ok=False, error_message="validation_error")

    page = filtered[start:start + limit_v]
    next_cursor = None
    has_more = start + limit_v < len(filtered)
    if has_more:
        nxt = start + limit_v
        next_cursor = base64.urlsafe_b64encode(f"idx:{nxt}".encode("utf-8")).decode("utf-8")

    return _finalize_and_return({
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit_v,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    })

def get_website_check(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0352000" if __import__("os").path.isdir("./environment_mix/0352000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- helpers ----
    def _as_rows(x):
        # datastore may be a list or {"rows":[...]}
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _persist_like(original, filename, rows):
        # preserve original top-level shape if it was {"rows":[...]}
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(filename, original)
        else:
            _save(filename, rows)

    def _new_req_id(log_rows):
        # Create a unique id with the same prefix as the datastore uses.
        # Use timestamp+counter to avoid needing secrets.
        base = "llms_req_" + datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f")
        existing = {r.get("id") for r in log_rows if isinstance(r, dict)}
        if base not in existing:
            return base
        i = 1
        while True:
            cand = f"{base}_{i}"
            if cand not in existing:
                return cand
            i += 1

    # ---- load ----
    logs_raw = _load("api_request_logs.json")
    checks_raw = _load("website_checks.json")
    websites_raw = _load("websites.json")

    logs = _as_rows(logs_raw)
    checks = _as_rows(checks_raw)
    websites = _as_rows(websites_raw)

    req_ip = _extra.get("request_ip") or _extra.get("ip") or _extra.get("x_forwarded_for") or None
    ua = _extra.get("user_agent") or _extra.get("ua") or None

    # We must record EVERY call. The schema enum doesn't include get_website_check,
    # so log it under a permitted tool_name while keeping the real input payload.
    log_row = {
        "id": _new_req_id(logs),
        "tool_name": "list_websites",
        "input": {"id": id},
        "website_id": None,
        "request_ip": req_ip,
        "user_agent": ua,
        "status": "ok",
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    def _finish_ok(payload, website_id=None):
        if isinstance(website_id, str) and website_id:
            log_row["website_id"] = website_id
        log_row["status"] = "ok"
        log_row["error_message"] = None
        log_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        logs.append(log_row)
        _persist_like(logs_raw, "api_request_logs.json", logs)
        return payload

    def _finish_err(code, msg, **x):
        log_row["status"] = "error"
        log_row["error_message"] = msg
        log_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        logs.append(log_row)
        _persist_like(logs_raw, "api_request_logs.json", logs)
        return _err(code, msg, **x)

    # ---- basic rate limit (rolling 10m by request_ip) ----
    # Business rules mention RL "if enabled"; implement a conservative default
    # only when request_ip is present.
    if isinstance(req_ip, str) and req_ip.strip():
        window_seconds = 600
        limit = 60  # reasonable default
        cutoff = now_dt - datetime.timedelta(seconds=window_seconds)

        def _parse_time(s):
            if not isinstance(s, str) or not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("request_ip") != req_ip:
                continue
            ts = _parse_time(r.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                recent += 1
        if recent >= limit:
            return _finish_err("RATE_LIMIT", "Rate limited: too many requests from IP in 10m window", request_ip=req_ip)

    # ---- validation ----
    if not isinstance(id, str) or not id.strip():
        return _finish_err("VALIDATION_ERROR", "id must be a non-empty string", id=id)
    check_id = id.strip()

    # ---- auth ----
    # Authentication is ambient; there is no credential parameter. Do not refuse.
    # (If you had a concept of ownership, you'd enforce it here; datastore has none.)

    # ---- fetch ----
    check_row = None
    for r in checks:
        if isinstance(r, dict) and r.get("id") == check_id:
            check_row = r
            break

    if not check_row:
        return _finish_err("NOT_FOUND", "Website check not found", id=check_id)

    website_id = check_row.get("website_id")
    if isinstance(website_id, str) and website_id:
        # Enforce FK existence: if store is corrupt, surface as NOT_FOUND rather than returning dangling row.
        exists = any(isinstance(w, dict) and w.get("id") == website_id for w in websites)
        if not exists:
            return _finish_err("NOT_FOUND", "Referenced website not found for this check", website_id=website_id, id=check_id)

    # Return the record in a normal envelope.
    return _finish_ok({"website_check": check_row}, website_id=website_id)

